// Save this file as 'comparison.js' in the src/components directory
import React from 'react';
import { useLocation } from 'react-router-dom';

const Comparison = () => {
  const location = useLocation();
  const { results, videoURL, seoData } = location.state || {};

  // Get the processed video path
  const getProcessedVideoPath = () => {
    if (results?.audio_processing?.enhanced_video_path) {
      const filename = results.audio_processing.enhanced_video_path.split('\\').pop();
      return `http://127.0.0.1:8000/media/${filename}`;
    }
    if (results?.video_upscaling?.processed_file_path) {
      const filename = results.video_upscaling.processed_file_path.split('\\').pop();
      return `http://127.0.0.1:8000/media/${filename}`;
    }
    return null;
  };

  const processedVideoPath = getProcessedVideoPath();
  const originalSeoData = {
    title: seoData?.original_title || 'No original title available',
    description: seoData?.original_description || 'No original description available',
    tags: seoData?.original_tags || [],
    keywords: seoData?.original_keywords || []
  };

  const optimizedSeoData = {
    title: seoData?.title || 'No optimized title available',
    description: seoData?.description || 'No optimized description available',
    tags: seoData?.tags || [],
    keywords: seoData?.keywords || []
  };

  const calculateImprovement = (original, optimized) => {
    const originalLength = original?.length || 0;
    const optimizedLength = optimized?.length || 0;
    if (originalLength === 0) return '0%';
    const improvement = ((optimizedLength - originalLength) / originalLength * 100).toFixed(1);
    return `${improvement}%`;
  };

  return (
    <div className="p-6 max-w-7xl mx-auto">
      <h1 className="text-3xl font-bold mb-8">Video Optimization Comparison</h1>

      <div className="grid grid-cols-2 gap-6 mb-8">
        <div>
          <h2 className="text-xl font-semibold mb-4">Original Video</h2>
          <video
            src={videoURL}
            controls
            className="w-full rounded-lg shadow-lg"
          />
        </div>
        <div>
          <h2 className="text-xl font-semibold mb-4">Optimized Video</h2>
          <video
            src={processedVideoPath}
            controls
            className="w-full rounded-lg shadow-lg"
          />
        </div>
      </div>

      <div className="grid grid-cols-2 gap-6">
        <div className="p-4 border rounded-lg shadow-sm">
          <h3 className="text-lg font-bold mb-4">Original SEO Metrics</h3>
          <div className="space-y-4">
            <div>
              <h4 className="font-medium">Title</h4>
              <p className="text-sm mt-1">{originalSeoData.title}</p>
            </div>
            <div>
              <h4 className="font-medium">Description</h4>
              <p className="text-sm mt-1">{originalSeoData.description}</p>
            </div>
            <div>
              <h4 className="font-medium">Tags</h4>
              <p className="text-sm mt-1">{originalSeoData.tags.join(', ') || 'No tags'}</p>
            </div>
            <div>
              <h4 className="font-medium">Keywords</h4>
              <p className="text-sm mt-1">{originalSeoData.keywords.join(', ') || 'No keywords'}</p>
            </div>
          </div>
        </div>

        <div className="p-4 border rounded-lg shadow-sm">
          <h3 className="text-lg font-bold mb-4">Optimized SEO Metrics</h3>
          <div className="space-y-4">
            <div>
              <h4 className="font-medium">Title</h4>
              <p className="text-sm mt-1">{optimizedSeoData.title}</p>
              <p className="text-xs text-green-600 mt-1">
                Improvement: {calculateImprovement(originalSeoData.title, optimizedSeoData.title)}
              </p>
            </div>
            <div>
              <h4 className="font-medium">Description</h4>
              <p className="text-sm mt-1">{optimizedSeoData.description}</p>
              <p className="text-xs text-green-600 mt-1">
                Improvement: {calculateImprovement(originalSeoData.description, optimizedSeoData.description)}
              </p>
            </div>
            <div>
              <h4 className="font-medium">Tags</h4>
              <p className="text-sm mt-1">{optimizedSeoData.tags.join(', ') || 'No tags'}</p>
              <p className="text-xs text-green-600 mt-1">
                Improvement: {calculateImprovement(originalSeoData.tags, optimizedSeoData.tags)}
              </p>
            </div>
            <div>
              <h4 className="font-medium">Keywords</h4>
              <p className="text-sm mt-1">{optimizedSeoData.keywords.join(', ') || 'No keywords'}</p>
              <p className="text-xs text-green-600 mt-1">
                Improvement: {calculateImprovement(originalSeoData.keywords, optimizedSeoData.keywords)}
              </p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Comparison;
